<script setup lang="ts">
import {computed,ref,useId} from 'vue';
import type {LabelColumn,LabelScope} from '@oxen/shared';
const props=defineProps<{columns:LabelColumn[];scope:LabelScope;modelValue:Record<string,string|string[]|null>;disabled?:boolean;initialCount?:number}>();
const emit=defineEmits<{ 'update:modelValue':[value:Record<string,string|string[]|null>] }>();
const prefix=useId(),expanded=ref(false);
const applicable=computed(()=>props.columns.filter(item=>!item.scopes||item.scopes.includes(props.scope)));
const visible=computed(()=>expanded.value?applicable.value:applicable.value.slice(0,props.initialCount??5));
function set(id:string,value:string|string[]|null){emit('update:modelValue',{...props.modelValue,[id]:value});}
function toggle(id:string,value:string,checked:boolean){const previous=Array.isArray(props.modelValue[id])?props.modelValue[id] as string[]:[];set(id,checked?[...new Set([...previous,value])]:previous.filter(item=>item!==value));}
</script>
<template><div class="dataset-label-fields"><div v-for="column in visible" :key="column.id" class="dataset-label-field" role="group" :aria-labelledby="prefix+'-'+column.id"><span class="dataset-field-heading"><strong :id="prefix+'-'+column.id">{{column.name}}</strong><button v-if="modelValue[column.id]!==undefined&&modelValue[column.id]!==null" type="button" :disabled="disabled" class="dataset-clear-label" :aria-label="'清空'+column.name" @click.prevent="set(column.id,null)">清空</button></span><small v-if="column.description" :id="prefix+'-'+column.id+'-help'">{{column.description}}</small><textarea v-if="column.type==='text'" :aria-label="column.name" :aria-describedby="column.description?prefix+'-'+column.id+'-help':undefined" :value="modelValue[column.id]??''" :disabled="disabled" rows="2" placeholder="尚未填写" @input="set(column.id,($event.target as HTMLTextAreaElement).value)"/><select v-else-if="column.type==='single'" :aria-label="column.name" :aria-describedby="column.description?prefix+'-'+column.id+'-help':undefined" :value="modelValue[column.id]??''" :disabled="disabled" @change="set(column.id,($event.target as HTMLSelectElement).value||null)"><option value="">尚未选择</option><option v-for="option in column.options" :key="option.value" :value="option.value" :title="option.description" :disabled="option.deprecated&&modelValue[column.id]!==option.value">{{option.displayName??option.value}}</option></select><span v-else class="dataset-multi-options"><label v-for="option in column.options" :key="option.value" :title="option.description"><input type="checkbox" :aria-label="column.name+'：'+(option.displayName??option.value)" :disabled="disabled||(option.deprecated&&!((modelValue[column.id] as string[]|undefined)?.includes(option.value)))" :checked="Array.isArray(modelValue[column.id])&&(modelValue[column.id] as string[]).includes(option.value)" @change="toggle(column.id,option.value,($event.target as HTMLInputElement).checked)"/><span>{{option.displayName??option.value}}</span></label></span></div><button v-if="applicable.length>(initialCount??5)" type="button" class="dataset-more" :aria-expanded="expanded" @click="expanded=!expanded">{{expanded?'收起更多标签':`展开更多标签（${applicable.length-(initialCount??5)}）`}}</button><p v-if="!applicable.length" class="dataset-muted">当前版本没有适用于此层级的标签。请向规范维护者反馈。</p></div></template>
<style scoped>.dataset-label-fields{display:grid;gap:18px}.dataset-label-field{display:flex;flex-direction:column;gap:7px;min-width:0}.dataset-field-heading{display:flex;align-items:center;justify-content:space-between;gap:8px;font-size:12px}.dataset-field-heading strong{font-weight:550}.dataset-label-field>small{color:var(--muted);font-size:11px;line-height:1.6}.dataset-label-field textarea,.dataset-label-field select{width:100%;padding:8px 10px;background:var(--bg);border:1px solid var(--line);border-radius:5px;color:var(--text);font:12px/1.6 inherit;min-height:35px}.dataset-clear-label{font-size:11px;color:var(--muted);padding:0;border:0;background:none}.dataset-clear-label:hover{color:var(--primary-hover)}.dataset-multi-options{display:flex;flex-wrap:wrap;gap:7px}.dataset-multi-options>label{display:flex;align-items:center;gap:6px;border:1px solid var(--line);border-radius:4px;padding:5px 7px;font-size:11px;background:var(--bg)}.dataset-multi-options input{accent-color:var(--primary);width:12px;height:12px}.dataset-more{border:1px solid var(--line);border-radius:5px;padding:9px;background:var(--surface-raised);color:var(--muted);font-size:12px;cursor:pointer}.dataset-more:hover{color:var(--text);border-color:var(--primary)}.dataset-muted{font-size:12px;color:var(--muted);line-height:1.8}</style>
